import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const {
    Group,
    Mesh,
    PlaneGeometry,
    BoxGeometry,
    Vector3,
    Color,
  } = THREE;

  const root = new Group();
  root.name = config.name || 'journal-thumbnail-card';

  const timelines = [];
  const disposables = [];
  const handlers = {};
  const basePosition = new Vector3(0, 0, 0);
  const baseScale = new Vector3(1, 1, 1);

  const cardWidth = 2.35;
  const cardHeight = 1.47;
  const stripHeight = 0.27;
  const imageHeight = cardHeight - stripHeight;

  const surfaceMaterial = new MeshBasicNodeMaterial({
    color: new Color('#0b0b10'),
  });
  const imageMaterial = new MeshBasicNodeMaterial({
    color: new Color('#e8ecf2'),
  });
  const accentMaterial = new MeshBasicNodeMaterial({
    color: new Color('#ff2a38'),
    transparent: true,
    opacity: 0,
  });

  disposables.push(surfaceMaterial, imageMaterial, accentMaterial);

  const cardGeometry = new PlaneGeometry(cardWidth, cardHeight);
  const imageGeometry = new PlaneGeometry(cardWidth, imageHeight);
  const stripGeometry = new PlaneGeometry(cardWidth, stripHeight);
  const edgeHorizontalGeometry = new PlaneGeometry(cardWidth, 0.025);
  const edgeVerticalGeometry = new PlaneGeometry(0.025, cardHeight);

  disposables.push(
    cardGeometry,
    imageGeometry,
    stripGeometry,
    edgeHorizontalGeometry,
    edgeVerticalGeometry,
  );

  const card = new Mesh(cardGeometry, surfaceMaterial);
  card.name = 'journal-thumbnail-surface';
  card.position.z = -0.025;
  root.add(card);

  const image = new Mesh(imageGeometry, imageMaterial);
  image.name = 'journal-thumbnail-image';
  image.position.y = stripHeight * 0.5;
  root.add(image);

  const caption = new Mesh(stripGeometry, surfaceMaterial);
  caption.name = 'journal-thumbnail-caption-strip';
  caption.position.y = -(cardHeight - stripHeight) * 0.5;
  caption.position.z = 0.012;
  root.add(caption);

  const edgeTop = new Mesh(edgeHorizontalGeometry, accentMaterial);
  const edgeBottom = new Mesh(edgeHorizontalGeometry, accentMaterial);
  const edgeLeft = new Mesh(edgeVerticalGeometry, accentMaterial);
  const edgeRight = new Mesh(edgeVerticalGeometry, accentMaterial);

  edgeTop.position.set(0, cardHeight * 0.5, 0.03);
  edgeBottom.position.set(0, -cardHeight * 0.5, 0.03);
  edgeLeft.position.set(-cardWidth * 0.5, 0, 0.03);
  edgeRight.position.set(cardWidth * 0.5, 0, 0.03);

  edgeTop.name = 'journal-thumbnail-focus-edge-top';
  edgeBottom.name = 'journal-thumbnail-focus-edge-bottom';
  edgeLeft.name = 'journal-thumbnail-focus-edge-left';
  edgeRight.name = 'journal-thumbnail-focus-edge-right';

  root.add(edgeTop, edgeBottom, edgeLeft, edgeRight);

  const imageUrl = config.imageUrl ?? config.intent?.visualSpec?.imageUrl;
  let loadedTexture = null;

  if (imageUrl) {
    ctx.textureLoader.loadTexture(imageUrl).then((texture) => {
      loadedTexture = texture;
      imageMaterial.map = texture;
      imageMaterial.needsUpdate = true;
    }).catch(() => {});
  }

  const showFocus = () => {
    gsap.to(accentMaterial, {
      opacity: 1,
      duration: 0.18,
      ease: 'power2.out',
    });
  };

  const hideFocus = () => {
    gsap.to(accentMaterial, {
      opacity: 0,
      duration: 0.22,
      ease: 'power2.out',
    });
  };

  const lift = () => {
    gsap.killTweensOf(root.position);
    const timeline = gsap.timeline();
    timeline.to(root.position, {
      y: basePosition.y + 0.15,
      duration: 0.3,
      ease: 'power3.out',
    });
    timelines.push(timeline);
  };

  const settle = () => {
    gsap.killTweensOf(root.position);
    const timeline = gsap.timeline();
    timeline.to(root.position, {
      y: basePosition.y,
      duration: 0.42,
      ease: 'power3.out',
    });
    timelines.push(timeline);
  };

  const press = () => {
    gsap.killTweensOf(root.scale);
    const timeline = gsap.timeline();
    timeline
      .to(root.scale, {
        x: 0.97,
        y: 0.97,
        duration: 0.12,
        ease: 'power2.out',
      })
      .to(root.scale, {
        x: baseScale.x,
        y: baseScale.y,
        z: baseScale.z,
        duration: 0.32,
        ease: 'back.out(2.2)',
      });
    timelines.push(timeline);
  };

  handlers.hover = (active = true) => {
    if (active) {
      lift();
      showFocus();
    } else {
      settle();
      hideFocus();
    }
  };

  handlers.focus = (active = true) => {
    if (active) showFocus();
    else hideFocus();
  };

  handlers.click = () => {
    press();
    ctx.emit('hub-journal.select', {
      node: config.name || 'journal-thumbnail-card',
    });
  };

  root.userData.handlers = handlers;
  root.userData.cleanup = () => {
    for (const timeline of timelines) {
      timeline.kill();
    }

    gsap.killTweensOf(root.position);
    gsap.killTweensOf(root.scale);
    gsap.killTweensOf(accentMaterial);

    for (const resource of disposables) {
      if (resource && typeof resource.dispose === 'function') {
        resource.dispose();
      }
    }

    if (loadedTexture && typeof loadedTexture.dispose === 'function') {
      loadedTexture.dispose();
    }

    root.clear();
  };

  return root;
}
